<?php
if(!defined('ABSPATH'))exit;
function legacyx_ai_context_clients(){if(!current_user_can('legacyx_manage_clients'))return array();return get_posts(array('post_type'=>'legacyx_client','post_status'=>'any','numberposts'=>100,'orderby'=>'title','order'=>'ASC'));}
function legacyx_ai_context_client($client_id){$client_id=absint($client_id);if(!$client_id||!current_user_can('legacyx_manage_clients'))return array();$p=get_post($client_id);if(!$p||$p->post_type!=='legacyx_client')return array();$intel=function_exists('legacyx_client_intelligence_snapshot')?legacyx_client_intelligence_snapshot($client_id):array();return array('id'=>$client_id,'name'=>$p->post_title,'client_id'=>get_post_meta($client_id,'_legacyx_client_id',true),'business'=>get_post_meta($client_id,'_legacyx_business_name',true),'status'=>get_post_meta($client_id,'_legacyx_status',true),'intel'=>$intel);}
function legacyx_ai_context_classify($q){$q=strtolower($q);if(strpos($q,'billing')!==false||strpos($q,'balance')!==false||strpos($q,'invoice')!==false)return'billing';if(strpos($q,'application')!==false||strpos($q,'funding')!==false)return'applications';if(strpos($q,'workflow')!==false||strpos($q,'task')!==false||strpos($q,'delivery')!==false)return'delivery';if(strpos($q,'client')!==false||strpos($q,'relationship')!==false)return'relationships';return'executive';}
function legacyx_ai_context_answer($question,$client_id=0){$question=sanitize_text_field($question);$mode=legacyx_ai_context_classify($question);$d=legacyx_ai_advisor_brief();$client=legacyx_ai_context_client($client_id);$out=array();if($client){$out[]='Context: '.$client['name'].($client['business']?' · '.$client['business']:'').'.';$i=$client['intel'];if($i){$out[]='Relationship posture: '.$i['priority'].' ('.$i['overall'].'/100).';if($mode==='billing')$out[]='Billing Operations signal: '.$i['billing_score'].'/100; recorded past-due items: '.$i['past_due'].'.';elseif($mode==='applications')$out[]='Application Activity signal: '.$i['application_score'].'/100; stalled application records: '.$i['app_stalled'].'.';elseif($mode==='delivery')$out[]='Delivery signal: '.$i['delivery'].'/100; overdue workflow: '.$i['overdue'].'; waiting on client: '.$i['waiting'].'.';else foreach(array_slice($i['recs'],0,3) as $r)$out[]=$r;}return $out;}
$s=$d['snapshot'];$out[]='Firm context: '.$d['band'].' operating posture ('.$s['overall'].'/100).';if($mode==='billing'){$out[]='Billing Operations signal: '.$s['revenue'].'/100.';$out[]='Recorded outstanding balance: '.(function_exists('legacyx_money')?legacyx_money($s['outstanding']):number_format($s['outstanding'],2)).'.';}elseif($mode==='applications'){$out[]='Recorded applications: '.$s['apps'].'; approved/funded status records: '.$s['approved'].'.';$out[]='Review application readiness and aging records without interpreting this as a funding decision.';}elseif($mode==='delivery'){$out[]='Client Delivery signal: '.$s['delivery'].'/100; open workflow: '.$s['open_work'].'; completed workflow: '.$s['completed_work'].'.';}elseif($mode==='relationships'){$out[]='Relationship Growth signal: '.$s['growth'].'/100; recorded client relationships: '.$s['clients'].'.';}foreach(array_slice($d['recommendations'],0,2) as $r)$out[]=$r[0].': '.$r[1];return $out;}
function legacyx_ai_context_form(){if(!current_user_can('legacyx_view_reports'))return;$clients=legacyx_ai_context_clients();$question=isset($_POST['legacyx_ai_question'])?sanitize_text_field(wp_unslash($_POST['legacyx_ai_question'])):'';$client_id=isset($_POST['legacyx_ai_client'])?absint($_POST['legacyx_ai_client']):0;$answer=array();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['legacyx_ai_context_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_ai_context_nonce'])),'legacyx_ai_context')){$answer=legacyx_ai_context_answer($question,$client_id);}?>
<section class="lxa-conversation"><div class="lxa-conv-head"><span>CONVERSATION & CONTEXT ENGINE</span><h2>Ask Legacy X Advisor</h2><p>Ask an operational question using current Firm OS context. Select a client relationship when you need a Client 360-level brief.</p></div><form method="post" action="<?php echo esc_url(admin_url('admin.php?page=legacyx-ai-advisor'));?>"><?php wp_nonce_field('legacyx_ai_context','legacyx_ai_context_nonce');?><div class="lxa-conv-controls"><select name="legacyx_ai_client"><option value="0">Firm-wide context</option><?php foreach($clients as $c):?><option value="<?php echo esc_attr($c->ID);?>" <?php selected($client_id,$c->ID);?>><?php echo esc_html($c->post_title);?></option><?php endforeach;?></select><input type="text" name="legacyx_ai_question" maxlength="240" required value="<?php echo esc_attr($question);?>" placeholder="Example: What deserves management attention right now?"><button class="button button-primary" type="submit">Ask Advisor</button></div></form><?php if($answer):?><div class="lxa-conv-answer"><small>EXPLAINABLE RESPONSE</small><?php foreach($answer as $i=>$line):?><article><b><?php echo esc_html(sprintf('%02d',$i+1));?></b><p><?php echo esc_html($line);?></p></article><?php endforeach;?></div><?php endif;?><small class="lxa-conv-note">Foundation mode uses deterministic Firm OS rules and authorized stored records only. It does not send this question or client context to an external AI provider.</small></section><?php }
function legacyx_ai_context_inject(){if(!current_user_can('legacyx_view_reports'))return;$screen=get_current_screen();if(!$screen||$screen->id!=='firm-os_page_legacyx-ai-advisor')return;ob_start();legacyx_ai_context_form();$html=ob_get_clean();?><div id="lxa-context-source" style="display:none"><?php echo $html;?></div><script>document.addEventListener('DOMContentLoaded',function(){var s=document.getElementById('lxa-context-source'),grid=document.querySelector('.lxa-ai-grid');if(s&&grid){var w=document.createElement('div');w.innerHTML=s.innerHTML;grid.insertAdjacentElement('afterend',w.firstElementChild);s.remove();}});</script><?php }add_action('admin_footer','legacyx_ai_context_inject',12);
function legacyx_ai_context_styles($hook){if($hook!=='firm-os_page_legacyx-ai-advisor')return;wp_register_style('legacyx-ai-context',false);wp_enqueue_style('legacyx-ai-context');$css='.lxa-conversation{background:#fff;border:1px solid #ded8ce;padding:28px;margin-top:18px}.lxa-conv-head span,.lxa-conv-answer>small{font-size:11px;font-weight:800;letter-spacing:.16em;color:#f05a16}.lxa-conv-head h2{font:29px Georgia,serif;margin:5px 0 8px}.lxa-conv-head p{color:#706a62}.lxa-conv-controls{display:grid;grid-template-columns:260px 1fr auto;gap:10px;margin-top:20px}.lxa-conv-controls select,.lxa-conv-controls input{min-height:42px}.lxa-conv-answer{background:#171512;color:#fff;padding:24px;margin-top:20px}.lxa-conv-answer article{display:grid;grid-template-columns:42px 1fr;gap:12px;border-top:1px solid #39352f;padding:14px 0}.lxa-conv-answer article b{color:#f05a16;font:20px Georgia,serif}.lxa-conv-answer article p{margin:0;color:#e4dfd7}.lxa-conv-note{display:block;color:#817a72;margin-top:14px}@media(max-width:800px){.lxa-conv-controls{grid-template-columns:1fr}}';wp_add_inline_style('legacyx-ai-context',$css);}add_action('admin_enqueue_scripts','legacyx_ai_context_styles');
